TIER = {
    "Standard": {"per_1m": 4.0, "free": 4_000_000},
    "Wavenet": {"per_1m": 16.0, "free": 1_000_000},
    "Neural2": {"per_1m": 16.0, "free": 1_000_000},
    "Studio": {"per_1m": 160.0, "free": 100_000},
    "Chirp3-HD": {"per_1m": 30.0, "free": 0},
}

ENCODINGS = {"MP3", "LINEAR16", "OGG_OPUS", "MULAW", "ALAW"}

MAX_REQUEST_BYTES = 5000


def tier_of(voice_name):
    parts = voice_name.split("-")
    if len(parts) < 4:
        raise ValueError(f"malformed voice name {voice_name!r}")
    if parts[2] == "Chirp3" and parts[3] == "HD":
        return "Chirp3-HD"
    if parts[2] in TIER:
        return parts[2]
    raise ValueError(f"unknown tier in voice name {voice_name!r}")


def monthly_cost(chars, tier):
    if tier not in TIER:
        raise ValueError(f"unknown tier {tier!r}")
    billable = max(0, chars - TIER[tier]["free"])
    return billable / 1_000_000 * TIER[tier]["per_1m"]


def billable_characters(text=None, ssml=None):
    if (text is None) == (ssml is None):
        raise ValueError("exactly one of text or ssml is required")
    return len(text if text is not None else ssml)


def input_bytes(text=None, ssml=None):
    if (text is None) == (ssml is None):
        raise ValueError("exactly one of text or ssml is required")
    return len((text if text is not None else ssml).encode("utf-8"))


def validate_audio_config(config):
    encoding = config.get("audioEncoding")
    if encoding not in ENCODINGS:
        raise ValueError(f"unknown audio encoding {encoding!r}")
    rate = config.get("speakingRate", 1.0)
    if not 0.25 <= rate <= 4.0:
        raise ValueError(f"speakingRate must be between 0.25 and 4.0, got {rate}")
    pitch = config.get("pitch", 0.0)
    if not -20.0 <= pitch <= 20.0:
        raise ValueError(f"pitch must be between -20 and 20 semitones, got {pitch}")
    return config


def build_request(language_code, text=None, ssml=None, name=None,
                  ssml_gender=None, audio_config=None):
    size = input_bytes(text=text, ssml=ssml)
    if size > MAX_REQUEST_BYTES:
        raise ValueError(
            f"input is {size} bytes; the synchronous limit is {MAX_REQUEST_BYTES} "
            "bytes - chunk it or use the long audio API")
    voice = {"languageCode": language_code}
    if name is not None:
        if not name.startswith(language_code + "-"):
            raise ValueError(
                f"voice {name!r} does not belong to language {language_code!r}")
        tier_of(name)
        voice["name"] = name
    elif ssml_gender is not None:
        voice["ssmlGender"] = ssml_gender
    config = validate_audio_config(dict(audio_config or {"audioEncoding": "MP3"}))
    return {
        "input": {"text": text} if text is not None else {"ssml": ssml},
        "voice": voice,
        "audioConfig": config,
    }
